import XCTest
final class ProbeTests:XCTestCase {
func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);var n=0;while !q.allElementsBoundByIndex.contains(where:{$0.isHittable}) && n<8{let sv=app.scrollViews.firstMatch;if q.firstMatch.frame.midY<sv.frame.minY+35{sv.swipeDown()}else{sv.swipeUp()};n+=1};if !q.allElementsBoundByIndex.contains(where:{$0.isHittable}),let e=q.allElementsBoundByIndex.first(where:{$0.isEnabled && $0.frame.minY>0 && $0.frame.maxY<app.frame.maxY}){e.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:0.5)).tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name+app.debugDescription);return};b.tap()}
func type(_ f:XCUIElement,_ value:String){f.tap();XCTAssertTrue(XCUIApplication(bundleIdentifier:"com.example.fancy.dev").keyboards.firstMatch.waitForExistence(timeout:10));for c in value{f.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
func option(_ app:XCUIApplication,_ name:String){let q=app.otherElements.matching(NSPredicate(format:"label == %@",name));XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);let e=q.firstMatch;var n=0;while !e.isHittable && n<8{let scroll=app.scrollViews.firstMatch;if e.frame.midY<scroll.frame.minY+35{scroll.swipeDown()}else{scroll.swipeUp()};n+=1};XCTAssertTrue(e.isHittable,app.debugDescription);e.tap()}
func shot(_ app:XCUIApplication,_ name:String){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
func testNativeM3Reference179(){continueAfterFailure=false;let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.terminate();app.launch();let decline=app.buttons["Decline analytics"];if decline.waitForExistence(timeout:5){decline.tap()};tap(app,"Meals, tab, 2 of 5");option(app,"Past");let label="A relaxed meal together, Fri 23 Oct · 00:00 BST, 2 of 2 confirmed";let q=app.buttons.matching(NSPredicate(format:"label == %@",label));XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);let count=q.count;var found=false;for index in 0..<count{let card=app.buttons.matching(NSPredicate(format:"label == %@",label)).element(boundBy:index);card.tap();if app.buttons["After the meal"].waitForExistence(timeout:3){found=true;break};XCTAssertTrue(app.staticTexts["Cancelled"].firstMatch.exists,app.debugDescription);tap(app,"Back")};XCTAssertTrue(found,app.debugDescription);tap(app,"After the meal");XCTAssertTrue(app.staticTexts["QA Final Applicant · Came · they reported"].firstMatch.waitForExistence(timeout:12),app.debugDescription);XCTAssertTrue(app.staticTexts["QA Final Applicant · Your host report: didn’t come"].firstMatch.exists,app.debugDescription);shot(app,"native179-persisted-self-priority");let f=app.textViews["Reference for QA Final Applicant"];var n=0;while !f.isHittable && n<8{app.scrollViews.firstMatch.swipeUp();n+=1};XCTAssertTrue(f.isHittable,app.debugDescription);f.tap();f.typeText("Friendly conversation at this synthetic meal.");let t=app.staticTexts["Public references"].firstMatch;if t.exists && t.isHittable{t.tap()};if app.keyboards.firstMatch.exists{app.staticTexts["Reference for QA Final Applicant"].firstMatch.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:0.5)).tap()};tap(app,"Save reference for QA Final Applicant");XCTAssertTrue(app.staticTexts["Reference saved."].firstMatch.waitForExistence(timeout:12),app.debugDescription);tap(app,"I’d meet QA Final Applicant again");XCTAssertTrue(app.staticTexts["Choice saved privately."].firstMatch.waitForExistence(timeout:12),app.debugDescription);shot(app,"native179-reference-private-choice");print("QA_NATIVE179_REFERENCE_CHOICE_PASS\n"+app.debugDescription)}
}
